const headers = $input.first().json.headers || {};
const token   = headers['x-internal-token'] || headers['X-Internal-Token'];

if (!token || token !== $env.INTERNAL_WEBHOOK_SECRET) {
  throw new Error('UNAUTHORIZED_REQUEST: invalid or missing token');
}

return [{ json: $input.first().json.body || $input.first().json }];

// Merge webhook trigger payload with DB lead record
const trigger = $items('Lock Meeting Proposal')[0].json;
const lead    = $items('Load Lead')[0]?.json;

if (!lead || !lead.id) {
  throw new Error(`LEAD_NOT_FOUND: ${trigger.lead_id}`);
}

const parseCol = (v) => {
  if (!v) return {};
  if (typeof v === 'object') return v;
  try { return JSON.parse(v); } catch(e) { return {}; }
};

return [{
  json: {
    ...lead,
    brief:           parseCol(lead.brief),
    meeting_context: trigger.meeting_context || null,
    urgency:         trigger.urgency || 'MEDIUM',
    trigger_event:   trigger.event  || 'intent.interested',
    triggered_at:    new Date().toISOString()
  }
}];

// ── Calendly pagination handler ─────────────────────────────────────────
// Calendly wraps results in { collection: [...], pagination: { next_page } }
// This node accumulates all pages by looping via HTTP until next_page is null.
//
// Strategy: fetch page 1 was already done by "Get Calendly Event Types".
// We read that result, then keep fetching next_page URLs until exhausted.
// All collections are merged and passed downstream as one flat array.

const firstPage   = $items('Get Calendly Event Types')[0].json;
let   allTypes    = [...(firstPage.collection || [])];
let   nextPageUrl = firstPage.pagination?.next_page || null;

// Safety cap: max 10 pages (1,000 event types) to prevent infinite loops
let  pageCount = 1;
const MAX_PAGES = 10;

while (nextPageUrl && pageCount < MAX_PAGES) {
  const resp = await $helpers.httpRequest({
    method:  'GET',
    url:     nextPageUrl,
    headers: {
      'Authorization': 'Bearer ' + $env.CALENDLY_API_KEY,
      'Content-Type':  'application/json'
    },
    timeout: 10000
  });

  const page = (typeof resp === 'string') ? JSON.parse(resp) : resp;
  allTypes    = allTypes.concat(page.collection || []);
  nextPageUrl = page.pagination?.next_page || null;
  pageCount++;
}

// ── Pick the best event type ─────────────────────────────────────────────
// Priority: discovery > intro > demo > first active
const active = allTypes.filter(e => e.active !== false);

const preferred = active.find(e => {
  const name = (e.name || '').toLowerCase();
  return name.includes('discovery') || name.includes('intro') || name.includes('demo');
}) || active[0];

if (!preferred) {
  throw new Error('CALENDLY_NO_EVENT_TYPE: no active event type found across ' + pageCount + ' pages');
}

const leadCtx = $items('Merge Trigger Context')[0].json;

// Build time window: +1d to +8d from now (skip today)
const now   = new Date();
const start = new Date(now.getTime() +  1 * 24 * 60 * 60 * 1000);
const end   = new Date(now.getTime() +  8 * 24 * 60 * 60 * 1000);

return [{
  json: {
    ...leadCtx,
    calendly_event_type_uri:  preferred.uri,
    calendly_event_type_name: preferred.name,
    calendly_scheduling_url:  preferred.scheduling_url,
    total_event_types_found:  allTypes.length,
    pages_fetched:            pageCount,
    slot_window_start:        start.toISOString(),
    slot_window_end:          end.toISOString()
  }
}];

// ── AI-Optimised Slot Selection ─────────────────────────────────────────
//
// Scoring model (higher = better for booking rate):
//
//   +30  Tue / Wed / Thu  (avoid Mon/Fri — low engagement days)
//   +20  Time 09:00–11:00 in lead's timezone  (peak focus window)
//   +10  Time 14:00–15:00 in lead's timezone  (post-lunch sweet spot)
//   -20  Monday or Friday
//   -30  Weekend (should never happen via Calendly, but guard anyway)
//   -10  Very early (<08:00) or very late (>17:00)
//   +5   Within next 3 days  (recency bias — higher intent = faster booking)
//   -5   More than 6 days away
//
// Lead timezone is inferred from company location stored in brief,
// or falls back to UTC.

const timesRaw  = $input.first().json;
const available = (timesRaw.collection || []).filter(t => t.status === 'available');

if (available.length === 0) {
  throw new Error('CALENDLY_NO_SLOTS: no available times in the next 7 days');
}

const ctx = $items('Fetch Available Slots')[0].json;

// ── Infer lead timezone ────────────────────────────────────────────────────
// Try: brief.timezone → brief.location → UTC fallback
const brief   = ctx.brief || {};
const tzGuess = brief.timezone || brief.time_zone || null;

// Map common country/region hints to IANA timezone strings
const TZ_MAP = {
  'US': 'America/New_York', 'USA': 'America/New_York',
  'UK': 'Europe/London',    'GB':  'Europe/London',
  'CA': 'America/Toronto',  'AU':  'Australia/Sydney',
  'IN': 'Asia/Kolkata',     'SG':  'Asia/Singapore',
  'DE': 'Europe/Berlin',    'FR':  'Europe/Paris',
  'AE': 'Asia/Dubai',       'JP':  'Asia/Tokyo',
};

const regionHint = (brief.country || brief.region || '').toUpperCase().slice(0, 2);
const tz = tzGuess || TZ_MAP[regionHint] || 'UTC';

// ── Score each slot ────────────────────────────────────────────────────────
const scoreSlot = (slot) => {
  let score = 0;

  // Parse into lead's timezone using Intl
  const startUTC = new Date(slot.start_time);

  // Get local parts for the lead's timezone
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone:     tz,
    weekday:      'short',   // Mon Tue Wed ...
    hour:         'numeric',
    hour12:       false
  }).formatToParts(startUTC);

  const weekday = parts.find(p => p.type === 'weekday')?.value || '';
  const hour    = parseInt(parts.find(p => p.type === 'hour')?.value || '12', 10);

  // Day-of-week scoring
  if (['Tue', 'Wed', 'Thu'].includes(weekday)) score += 30;
  if (['Mon', 'Fri'].includes(weekday))        score -= 20;
  if (['Sat', 'Sun'].includes(weekday))        score -= 30;

  // Time-of-day scoring (lead's local time)
  if (hour >= 9  && hour <= 11) score += 20;   // morning sweet spot
  if (hour >= 14 && hour <= 15) score += 10;   // post-lunch
  if (hour < 8   || hour > 17)  score -= 10;   // outside business hours

  // Recency: slots sooner are better (higher booking intent)
  const daysAway = (startUTC - new Date()) / (1000 * 60 * 60 * 24);
  if (daysAway <= 3) score += 5;
  if (daysAway >  6) score -= 5;

  return { slot, score, weekday, hour, daysAway: Math.round(daysAway * 10) / 10, tz };
};

// Score all, sort descending, pick top 3
const scored = available
  .map(scoreSlot)
  .sort((a, b) => b.score - a.score);

const top3 = scored.slice(0, 3);

// ── Format for email ─────────────────────────────────────────────────────
const formatSlot = ({ slot, score, tz: slotTz }) => {
  const d = new Date(slot.start_time);
  return {
    start_time:  slot.start_time,
    invitee_url: slot.invitee_url,
    score,
    timezone_used: slotTz,
    display: d.toLocaleString('en-US', {
      timeZone: slotTz,
      weekday:  'long',
      month:    'long',
      day:      'numeric',
      hour:     'numeric',
      minute:   '2-digit',
      timeZoneName: 'short'
    })
  };
};

const slots = top3.map(s => formatSlot(s));

return [{
  json: {
    ...ctx,
    slots,
    slot_count:       slots.length,
    scheduling_link:  ctx.calendly_scheduling_url,
    slot_timezone:    tz,
    slot_scores:      top3.map(s => ({ time: s.slot.start_time, score: s.score, day: s.weekday, hour: s.hour })),
    slot_summary:     slots.map((s, i) => `Option ${i+1}: ${s.display}`).join('\n'),
    total_candidates: available.length
  }
}];

