const raw = $input.first().json?.choices?.[0]?.message?.content
         || $input.first().json?.message?.content || '';

let email = {};
try {
  const start = raw.indexOf('{');
  const end   = raw.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('no JSON');
  email = JSON.parse(raw.slice(start, end + 1));
} catch(e) {
  // Fallback: use a simple template
  const ctx = $items('Select 3 Slots')[0].json;
  email = {
    subject: `Quick intro call — ${ctx.company}?`,
    body_text: `Hi ${ctx.first_name},\n\nWould love 20 mins to connect. A few times that work:\n\n${ctx.slot_summary}\n\nOr grab a time here: ${ctx.scheduling_link}\n\nBest`,
    body_html: `<p>Hi ${ctx.first_name},</p><p>Would love 20 mins to connect. A few times that work:</p><p>${ctx.slot_summary.replace(/\n/g,'<br>')}</p><p>Or <a href='${ctx.scheduling_link}'>grab a time here</a>.</p>`
  };
}

const ctx = $items('Select 3 Slots')[0].json;

return [{
  json: {
    ...ctx,
    proposal_subject:   email.subject   || '',
    proposal_body_text: email.body_text || '',
    proposal_body_html: email.body_html || '',
    generated_at:       new Date().toISOString()
  }
}];

const raw = $input.first().json?.choices?.[0]?.message?.content
         || $input.first().json?.message?.content || '';

let result = { approved: true, reason: 'ok' };
try {
  const s = raw.indexOf('{'); const e = raw.lastIndexOf('}');
  if (s !== -1 && e !== -1) result = JSON.parse(raw.slice(s, e + 1));
} catch(_) {}

const ctx = $items('Parse Proposal Email')[0].json;

return [{
  json: {
    ...ctx,
    guardrail_approved: result.approved !== false,
    guardrail_reason:   result.reason || 'ok'
  }
}];

