// Calendly sends invitee.created and invitee.canceled events
const body     = $input.first().json.body || $input.first().json;
const event    = body.event || '';
const payload  = body.payload || {};

const eventUri    = payload.event?.uri || payload.event || '';
const inviteeUri  = payload.invitee?.uri || '';
const inviteeName = payload.invitee?.name || '';
const inviteeEmail= (payload.invitee?.email || '').toLowerCase().trim();
const startTime   = payload.event?.start_time || payload.scheduled_event?.start_time || null;
const endTime     = payload.event?.end_time   || payload.scheduled_event?.end_time   || null;
const canceledAt  = payload.canceled_at || null;
const cancelReason= payload.cancel_reason || null;

if (!inviteeEmail) throw new Error('CALENDLY_PARSE_FAILED: no invitee email');

return [{
  json: {
    calendly_event_type: event,          // invitee.created | invitee.canceled
    event_uri:           eventUri,
    invitee_uri:         inviteeUri,
    invitee_name:        inviteeName,
    invitee_email:       inviteeEmail,
    start_time:          startTime,
    end_time:            endTime,
    canceled_at:         canceledAt,
    cancel_reason:       cancelReason,
    is_cancellation:     event === 'invitee.canceled',
    received_at:         new Date().toISOString()
  }
}];

