const err  = $input.first().error || {};
const msg  = err.message || 'Unknown error in WF-07';
const isAuth     = msg.includes('UNAUTHORIZED_REQUEST');
const isNoSlots  = msg.includes('CALENDLY_NO_SLOTS');
const isNoType   = msg.includes('CALENDLY_NO_EVENT_TYPE');
const isNoLead   = msg.includes('LEAD_NOT_FOUND');

return [{
  json: {
    status:       isAuth ? 'unauthorized' : isNoSlots ? 'no_slots' : isNoLead ? 'lead_not_found' : 'error',
    message:      msg,
    workflow:     'WF-07',
    timestamp:    new Date().toISOString(),
    execution_id: $execution.id
  }
}];

// ── Redis rate limiter for OpenAI calls ─────────────────────────────────
// Key: rate:ai:minute  (resets every 60 seconds via TTL)
// Limit: 60 calls per 60-second window.
// Strategy: INCR the counter. If it just became 1, set TTL=60s.
// Downstream IF node blocks execution if count > 60.

const redisKey = 'rate:ai:minute';

// Increment and get new value
const newCount = await $helpers.redis.incr(redisKey);

// Only set TTL on the first call in the window (avoids resetting the window)
if (newCount === 1) {
  await $helpers.redis.expire(redisKey, 60);
}

return [{
  json: {
    ...$input.first().json,
    ai_rate_count:  newCount,
    ai_rate_key:    redisKey,
    ai_rate_limit:  60,
    rate_ok:        newCount <= 60
  }
}];

